function change(mutator,label){if(!ready){status('Aguarde o carregamento do projeto.',true);return false;}try{const next=clone(project);mutator(next);normalizeProject(next);validate(next);assertLayoutChange(project,next);history.push({project:clone(project),label:label||changeDescription(project,next)});if(history.length>40)history.shift();future=[];clearReceipt();project=next;generation++;dirty=true;route=[];routeLinks=[];saveDraft();render();scheduleSave();return true;}catch(err){throw err;}}
function saveDraft(){try{localStorage.setItem('atlas-draft-v3',JSON.stringify({revision,project}));}catch{}}
function scheduleSave(){saveState('Alterações por guardar');status('Alterações por guardar…');clearTimeout(saveTimer);saveTimer=setTimeout(saveProject,650);}
async function saveProject(){if(!ready||!dirty||saving||conflict)return;saving=true;saveState('A guardar…');status('A guardar…');const g=generation;try{const response=await fetch('/api/project',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,project})});const result=await response.json();if(response.status===409){conflict=true;throw new Error('Há alterações noutra sessão. Exporte o projeto e recarregue antes de continuar.');}if(!response.ok)throw new Error(result.error||'Não foi possível guardar.');revision=result.revision;if(g===generation){dirty=false;try{localStorage.removeItem('atlas-draft-v3');}catch{}saveState('Guardado na conta');status('Guardado na tua conta');}else saveDraft();}catch(err){saveState('Não guardado · tentar novamente',true);status(err.message+' Use «Guardar» para tentar novamente.',true);}finally{saving=false;if(dirty&&g!==generation&&!conflict)scheduleSave();}}
async function load(){try{const response=await fetch('/api/project',{cache:'no-store'});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível carregar.');if(result.project)project=normalizeProject(validate(result.project));revision=result.revision||0;ready=true;saveState(result.project?'Guardado na conta':'Exemplo · ainda não guardado');status(result.project?'Projeto carregado':'Exemplo pronto a personalizar');let draft;try{draft=JSON.parse(localStorage.getItem('atlas-draft-v3')||'null');}catch{}if(draft&&confirm('Foi encontrado um rascunho não guardado neste navegador. Pretende recuperá-lo?')){if(draft.revision!==revision){status('O rascunho é de outra revisão. Exporte-o antes de substituir o projeto guardado.',true);try{await exportProtected(draft.project);}catch(err){status('O rascunho continua neste navegador. '+err.message,true);}}else{project=normalizeProject(validate(draft.project));dirty=true;generation++;scheduleSave();}}render();}catch(err){status(err.message+' Recarregue a página para voltar a tentar. Pode exportar o exemplo.',true);ready=false;render();}}
