function openSearchDevice(id){const d=project.devices.find(d=>d.id===id);if(!d)return;$('#mapInteraction').value='navigate';$('#mapInteraction').onchange({target:$('#mapInteraction')});siteFilter='';vlanFilter=0;query='';$('#search').value='';if(d.room)features.openRoom(d.room);else features.openFloor(d.floor||'');select('devices',id);$('#inventoryMap')?.click();$('#planSelection')?.click();}
